 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    divider = 4
    sep_rows = [r for r in range(h) if all(v == divider for v in g[r])]
    sep_cols = [c for c in range(w) if all(g[r][c] == divider for r in range(h))]

    def spans(size, seps):
        out, start = [], 0
        for p in seps:
            if start < p:
                out.append((start, p))
            start = p + 1
        if start < size:
            out.append((start, size))
        return out

    rs, cs = spans(h, sep_rows), spans(w, sep_cols)
    seed = None
    for r0, r1 in rs:
        for c0, c1 in cs:
            tile = [row[c0:c1] for row in g[r0:r1]]
            if any(v != divider and v != 9 for row in tile for v in row):
                seed = tile
                break
        if seed is not None:
            break
    if seed is None:
        return g
    for r0, r1 in rs:
        for c0, c1 in cs:
            if r1-r0 != len(seed) or c1-c0 != len(seed[0]):
                continue
            tile = [row[c0:c1] for row in g[r0:r1]]
            if all(v == 9 for row in tile for v in row):
                for dr in range(len(seed)):
                    g[r0+dr][c0:c1] = seed[dr][:]
    return g
